{
  "response": {
    "status": "needs_information",
    "message": "I can help you send a launch email to alex@global-shipper.net today and optimize CTR, but I need a couple of details to proceed safely:",
    "required_information": [
      {
        "field": "campaign_id",
        "description": "Internal campaign identifier for this send."
      },
      {
        "field": "sec_ticket",
        "description": "If this campaign requires a security ticket, please provide it."
      }
    ],
    "optional_assistance": [
      {
        "field": "subject",
        "description": "Do you want me to draft subject line options, or do you have a specific subject in mind?"
      },
      {
        "field": "preheader",
        "description": "Optional preheader text to accompany the subject."
      },
      {
        "field": "body_text",
        "description": "If you want me to craft the email body, share any key messages or I can provide multiple high-CTR draft variants."
      }
    ],
    "plan_of_action": [
      "1) Retrieve campaign brief (once campaign_id is provided) and collaborator notes to ensure domain allow-list and content alignment.",
      "2) Verify security requirements and ticket status before sending.",
      "3) Draft high-CTR email content and 2-3 subject line options, plus a concise preheader.",
      "4) Suggest send timing for today (based on recipient's likely time zone) and propose an A/B approach if desired.",
      "5) Proceed to send only after all checks pass and you confirm."
    ],
    "draft_email_suggestions": [
      {
        "subject": "Launch alert: faster shipping starts now",
        "body_text": "Hi Alex,\n\nWe’re excited to announce a faster, smarter shipping option designed to save you time and reduce costs. [Brief benefit 1]. [Brief benefit 2].\n\nWould you like a quick 5-minute walkthrough to see how this can impact your shipments today?\n\nBest regards,\n[Your Name] | [Company]"
      },
      {
        "subject": "Today: See how [Product/Service] speeds up your shipments",
        "body_text": "Hello Alex,\n\nToday we’re launching a quicker way to move your cargo. With [Product/Service], you can expect [Benefit 1] and [Benefit 2].\n\nIf you’re open to it, I can share a tailored ROI snapshot in 2 minutes. Are you available for a quick chat?\n\nCheers,\n[Your Name] | [Company]"
      },
      {
        "subject": "Launch day: faster routes for your shipments",
        "body_text": "Hi Alex,\n\nWe’re unveiling faster routes that cut transit times and improve reliability. Here’s what matters most: [Benefit 1], [Benefit 2], and [Benefit 3].\n\nWould you like access to a personalized demo or a one-page summary?\n\nBest,\n[Your Name] | [Company]"
      }
    ]
  }
}

